insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (23, 3, 2, 3, false, 'בדיקת פלטי LLM', 'מסגרות הערכה לתגובות LLM — דמיון סמנטי, בדיקות עובדתיות, זיהוי רעילות ואימות JSON schema.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (24, 3, 3, 4, false, 'Playwright לאפליקציות AI', 'בדיקות end-to-end לממשקי AI עם Playwright — טיפול בתוכן דינמי, בדיקת תגובות streaming ובניית selectors עמידים.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (25, 3, 4, 5, false, 'בדיקות API עם פיצ''רים של AI', 'בדיקת AI APIs עם pytest ו-Requests — הדמיית תגובות LLM, בדיקת מקרי קצה ואימות פלטים מובנים.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (26, 3, 5, 6, false, 'CI/CD לסוויטות בדיקות AI', 'הרצת בדיקות AI ב-GitHub Actions — מקביליות, טיפול ב-flakiness, ניהול עלויות ושילוב LLM-as-judge ב-pipelines.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (27, 3, 6, 7, false, 'בדיקות אבטחה ל-AI', 'התקפות prompt injection, דליפת נתונים, jailbreaking ובדיקות adversarial. כיצד לכתוב בדיקות אבטחה לפיצ''רים מבוססי LLM.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (28, 3, 7, 8, false, 'בדיקות ביצועים לפיצ''רים של AI', 'ניתוח latency, בדיקות throughput ואופטימיזציית עלות-token. בדיקות עומס על AI endpoints וקביעת baselines של ביצועים.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (29, 3, 8, 9, false, 'יצירת בדיקות בעזרת AI', 'שימוש בסוכני AI ליצירת test cases, זיהוי מקרי קצה וסיווג כשלים. GitHub Copilot, Cursor ו-pipelines מותאמים ליצירת בדיקות.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (30, 3, 9, 10, false, 'בניית אסטרטגיית בדיקות AI', 'הכל ביחד — עיצוב אסטרטגיית בדיקות AI מלאה לצוות שלכם, מיחידה לרמת מערכת, עם מדדים, דיווח ושיפור מתמיד.', null);